const carePlaces=[['community','自宅等（短期入所・施設入所を除く）'],['group','認知症対応型グループホーム'],['specified','特定施設（指定特定施設等）'],['hospital','保険医療機関に入院中（短期入所療養介護を除く）'],['roken','介護老人保健施設に入所中'],['shortMedical','短期入所療養介護・介護予防短期入所療養介護'],['tokuyo','特養・地域密着型介護老人福祉施設'],['shortLife','短期入所生活介護・介護予防短期入所生活介護'],['careHospital','介護医療院に入所中'],['notCare','要介護・要支援の被保険者等ではない'],['facility','その他・施設区分が不明']];
