function careDecision(a){const place=a.careSetting;
if(['hospital','roken'].includes(place))return [{state:'fail',label:'給付調整・別紙１のこの患者区分では、当該項目は算定対象外です（PDF17ページ）。'}];
if(place==='shortMedical'&&['roken','other'].includes(a.shortRoom))return [{state:'fail',label:'給付調整・別紙１の短期入所療養介護の該当区分では、当該項目は算定対象外です（PDF17ページ）。'}];
if(place==='careHospital'||(place==='shortMedical'&&a.shortRoom==='careHospital'))return [{state:'unknown',label:'介護医療院は別紙２による別の給付調整です。別紙１の判定を流用できません。療養室・給付内容の個別確認が残っています。'}];
if(place==='facility')return [{state:'unknown',label:'施設区分を特定できないため、給付調整の判定を保留しています。'}];
return [];}
